css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .62); position: relative; }
.loader::before { content: ''; position: absolute; top: 19%; left: 22%; width: 58%; height: 6%; background: repeating-linear-gradient(90deg, color-mix(in srgb, #000 34%, var(--accent-2)) 0 calc(var(--loader-size) * .022), transparent calc(var(--loader-size) * .022) calc(var(--loader-size) * .046)); animation: chain-top calc(var(--loader-speed) * .8) linear infinite; }
.loader::after { content: ''; position: absolute; bottom: 19%; left: 22%; width: 58%; height: 6%; background: repeating-linear-gradient(90deg, color-mix(in srgb, #000 34%, var(--accent-2)) 0 calc(var(--loader-size) * .022), transparent calc(var(--loader-size) * .022) calc(var(--loader-size) * .046)); animation: chain-bottom calc(var(--loader-speed) * .8) linear infinite; }
.loader span { position: absolute; border-radius: 50%; background: repeating-conic-gradient(from 0deg, var(--accent) 0 11deg, color-mix(in srgb, #000 26%, var(--accent)) 11deg 22deg); box-shadow: inset 0 0 0 calc(var(--loader-size) * .045) color-mix(in srgb, #fff 24%, var(--accent-2)); animation: sprocket calc(var(--loader-speed) * 2) linear infinite; }
.loader span:nth-child(1) { left: 2%; top: 11%; width: calc(var(--loader-size) * .4); height: calc(var(--loader-size) * .4); }
.loader span:nth-child(2) { right: 2%; top: 22%; width: calc(var(--loader-size) * .26); height: calc(var(--loader-size) * .26); animation-duration: calc(var(--loader-speed) * 1.3); }
@keyframes sprocket { to { transform: rotate(360deg); } }
@keyframes chain-top { to { background-position: calc(var(--loader-size) * .046) 0; } }
@keyframes chain-bottom { to { background-position: calc(var(--loader-size) * -.046) 0; } }
